<script setup>
import { onMounted, reactive, ref, watch } from 'vue'
import FloatingWindow from '../components/common/FloatingWindow.vue'
import NeonPanel from '../components/common/NeonPanel.vue'
import { useAppStore } from '../stores/app'
const store = useAppStore(); const profile = ref(null); const passwordWindow = ref(false); const mfaWindow = ref(false); const mfa = ref(null); const notice = ref(''); const password = reactive({ currentPassword: '', newPassword: '' }); const code = ref('')
const themes = [{ id: 'purple', title: 'Purple Signal', detail: 'Current neon-violet command surface.' }, { id: 'ocean-wave', title: 'Ocean Wave', detail: 'Deep navy, cyan, and sea-glass signal colors.' }, { id: 'moderno', title: 'Moderno', detail: 'High-contrast graphite and grayscale controls.' }]
async function load() { profile.value = await store.profile(); applyTheme(profile.value.theme) }
function applyTheme(theme) { document.documentElement.dataset.theme = theme }
async function chooseTheme(theme) { await store.saveTheme(theme); profile.value.theme = theme; applyTheme(theme); notice.value = `${themes.find((item) => item.id === theme).title} saved.` }
async function savePassword() { await store.changePassword(password); password.currentPassword = ''; password.newPassword = ''; passwordWindow.value = false; notice.value = 'Password updated.' }
async function startMfa() { mfa.value = await store.beginMfaEnrollment(); code.value = ''; mfaWindow.value = true }
async function confirmMfa() { await store.confirmMfaEnrollment({ secret: mfa.value.secret, code: code.value }); await load(); mfaWindow.value = false; notice.value = 'Authenticator MFA enrolled.' }
async function removeMfa() { await store.disableMfa({ currentPassword: password.currentPassword }); password.currentPassword = ''; await load(); notice.value = 'MFA disabled.' }
watch(() => store.currentUser?.theme, applyTheme); onMounted(load)
</script>
<template><div class="profile-workspace"><div class="toolbar-row"><div><p class="section-eyebrow">Personal Security And Appearance</p><h2 class="page-title">My Profile</h2></div><v-chip v-if="profile" color="secondary" variant="tonal">{{ profile.role }}</v-chip></div><v-alert v-if="notice" type="success" density="compact" variant="tonal">{{ notice }}</v-alert><NeonPanel subtitle="Account Identity" title="Sign-in Security"><div v-if="profile" class="security-grid"><article><span>Email</span><strong>{{ profile.email }}</strong><small>{{ profile.entraEnabled ? 'Enterprise sign-in enabled' : 'Local account' }}</small></article><article><span>Password</span><strong>Protected</strong><v-btn size="small" variant="text" @click="passwordWindow = true">Change password</v-btn></article><article><span>Authenticator MFA</span><strong>{{ profile.mfaEnabled ? 'Enrolled' : 'Not enrolled' }}</strong><v-btn size="small" :color="profile.mfaEnabled ? 'warning' : 'success'" variant="text" @click="profile.mfaEnabled ? (passwordWindow = true) : startMfa()">{{ profile.mfaEnabled ? 'Disable with password' : 'Enroll MFA' }}</v-btn></article></div></NeonPanel><NeonPanel subtitle="Theme Library" title="Choose Your Operator Surface"><div class="theme-grid"><button v-for="theme in themes" :key="theme.id" class="theme-card" :class="[theme.id, { selected: profile?.theme === theme.id }]" @click="chooseTheme(theme.id)"><span class="swatches"><i/><i/><i/></span><strong>{{ theme.title }}</strong><small>{{ theme.detail }}</small></button></div></NeonPanel><FloatingWindow v-model="passwordWindow" title="Change Password / Disable MFA" :width="500" :start-x="370" :start-y="120"><form class="profile-form" @submit.prevent="savePassword"><v-text-field v-model="password.currentPassword" type="password" label="Current password"/><v-text-field v-model="password.newPassword" type="password" label="New password" hint="Use at least 12 characters." persistent-hint/><div class="actions"><v-btn v-if="profile?.mfaEnabled" color="warning" variant="text" @click="removeMfa">Disable MFA</v-btn><v-spacer/><v-btn variant="text" @click="passwordWindow = false">Cancel</v-btn><v-btn class="glass-button" type="submit">Update password</v-btn></div></form></FloatingWindow><FloatingWindow v-model="mfaWindow" title="Enroll Authenticator MFA" :width="620" :start-x="310" :start-y="100"><div v-if="mfa" class="profile-form"><v-alert type="info" density="compact" variant="tonal">Add this account in any TOTP authenticator. Scan the provisioning URI with an authenticator that supports URI import, or enter the setup key manually.</v-alert><v-text-field :model-value="mfa.secret" label="Setup key" readonly/><v-textarea :model-value="mfa.otpauthUri" label="Provisioning URI" rows="3" readonly/><v-text-field v-model="code" label="6-digit verification code" inputmode="numeric"/><div class="actions"><v-btn variant="text" @click="mfaWindow = false">Cancel</v-btn><v-btn class="glass-button" @click="confirmMfa">Verify and enable</v-btn></div></div></FloatingWindow></div></template>
<style scoped>.profile-workspace,.profile-form{display:grid;gap:14px}.security-grid,.theme-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:14px}.security-grid article,.theme-card{display:grid;gap:7px;padding:14px;border:1px solid var(--line);background:rgba(40,211,255,.05);text-align:left}.security-grid span,.security-grid small,.theme-card small{color:var(--muted);font-size:.75rem}.theme-card{cursor:pointer;color:var(--text)}.theme-card.selected{border-color:var(--cyan);box-shadow:0 0 18px color-mix(in srgb,var(--cyan) 24%,transparent)}.swatches{display:flex;gap:4px}.swatches i{width:22px;height:8px;background:var(--cyan)}.theme-card.ocean-wave .swatches i:nth-child(2){background:#159fd1}.theme-card.ocean-wave .swatches i:nth-child(3){background:#9ce9ea}.theme-card.moderno .swatches i{background:#eceff1}.theme-card.moderno .swatches i:nth-child(2){background:#8c9298}.theme-card.moderno .swatches i:nth-child(3){background:#191b1e}.actions{display:flex;align-items:center;gap:8px}@media(max-width:700px){.security-grid,.theme-grid{grid-template-columns:1fr}}</style>
